{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "add_diameter_dim",
      "category": "annotate",
      "description": "Diameter dimension of a circle/arc.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "CIRCLE or ARC to dimension — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "angle": {
            "type": "number",
            "description": "Direction of the leader (degrees, counter-clockwise)",
            "default": 45.0
          },
          "text": {
            "type": "string",
            "description": "Text override; '<>' stands for the measured value"
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Override text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "length_factor": {
            "type": "number",
            "description": "DIMLFAC: displayed value = measured length x factor, e.g. 1/0.325 on a sheet that shows the part at scale 0.325",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "op": "array_polar",
      "category": "edit",
      "description": "Polar array about a center: 'count' items (including the original) over 'total_angle'.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Array center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "count": {
            "type": "integer",
            "description": "Total number of items including the original",
            "minimum": 2,
            "maximum": 10000
          },
          "total_angle": {
            "type": "number",
            "description": "Angle to fill (degrees, counter-clockwise)",
            "default": 360.0
          },
          "rotate_items": {
            "type": "boolean",
            "description": "Rotate the copies (else only translate)",
            "default": true
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "center",
          "count"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_text",
      "category": "annotate",
      "description": "Single-line text.",
      "params": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "Text content"
          },
          "insert": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Alignment point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0,
            "default": 2.5
          },
          "rotation": {
            "type": "number",
            "description": "Rotation (degrees, counter-clockwise)",
            "default": 0.0
          },
          "align": {
            "type": "string",
            "enum": [
              "left",
              "center",
              "right",
              "middle",
              "middle_center",
              "top_left",
              "top_center",
              "bottom_center",
              "middle_left"
            ],
            "description": "Alignment of the insert point",
            "default": "left"
          },
          "style": {
            "type": "string",
            "description": "Text style (see create_text_style); default Standard"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "text",
          "insert"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_center_mark",
      "category": "annotate",
      "description": "Center mark of CIRCLEs / ARCs (AutoCAD CENTERMARK): a horizontal and a vertical LINE through each center, 'extension' beyond the radius. Layer CENTER with linetype CENTER unless given. With 'tag' the lines are tagged '<tag>.h' / '<tag>.v' (several targets: '<tag>.<i>.h').",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "CIRCLE / ARC entities — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "extension": {
            "type": [
              "number",
              "string"
            ],
            "description": "Overshoot past the circle (default: max(2, radius/2)) (drawing units, or string with unit e.g. '8mm')",
            "minimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
